import { readFileSync } from 'node:fs';
export type Point = [number, number];
export interface Example {
  id: string;
  point: Point;
  label: number;
}
export interface MultiExample {
  id: string;
  point: Point;
  class: number;
  role: string;
}
interface KernelName {
  name: string;
  index: number;
}
export type Kernel = KernelName &
  (
    | { kind: 'linear' }
    | { kind: 'poly'; degree: number; gamma: number; coef0: number }
    | { kind: 'rbf'; gamma: number }
  );
export interface Parameters {
  cs: number[];
  kernels: Kernel[];
  tau: number;
  eps: number;
  maxPasses: number;
  folds: number;
  learningCurve: number[];
  newtonIterations: number;
  multiName: string;
  multiC: number;
  pegasos: { lambda: number; iterations: number; seed: number };
  xMin: number;
  xMax: number;
  yMin: number;
  yMax: number;
  width: number;
  height: number;
}
const lines = (path: string) => readFileSync(path, 'ascii').split('\n').slice(0, -1);
function examples(path: string): Example[] {
  return lines(path)
    .slice(1)
    .map((line) => {
      const [id, x, y, label] = line.split(',');
      return { id, point: [Number(x), Number(y)], label: Number(label) };
    });
}
export function read() {
  const rows = lines('input/params.txt').map((line) => line.split(' '));
  const cs = rows[0].slice(1).map(Number);
  const kernels: Kernel[] = [];
  let i = 1;
  while (rows[i][0] === 'KERNEL') {
    const [, name, kind, a, b, c] = rows[i++];
    const base = { name, index: kernels.length };
    if (kind === 'linear') kernels.push({ ...base, kind });
    else if (kind === 'poly') {
      kernels.push({ ...base, kind, degree: Number(a), gamma: Number(b), coef0: Number(c) });
    } else kernels.push({ ...base, kind: 'rbf', gamma: Number(a) });
  }
  const r = rows.slice(i);
  const nums = r.map((row) => row.slice(1).map(Number));
  const params: Parameters = {
    cs,
    kernels,
    tau: nums[0][0],
    eps: nums[1][0],
    maxPasses: nums[2][0],
    folds: nums[3][0],
    learningCurve: nums[4],
    newtonIterations: nums[5][0],
    multiName: r[6][1],
    multiC: nums[6][1],
    pegasos: { lambda: nums[7][0], iterations: nums[7][1], seed: nums[7][2] },
    xMin: nums[8][0],
    xMax: nums[8][1],
    yMin: nums[9][0],
    yMax: nums[9][1],
    width: nums[10][0],
    height: nums[10][1],
  };
  const multi: MultiExample[] = lines('input/multiclass.csv')
    .slice(1)
    .map((line) => {
      const [id, x, y, c, role] = line.split(',');
      return { id, point: [Number(x), Number(y)], class: Number(c), role };
    });
  return {
    train: examples('input/train.csv'),
    test: examples('input/test.csv'),
    multiTrain: multi.filter((row) => row.role === 'train'),
    multiTest: multi.filter((row) => row.role === 'test'),
    params,
  };
}

import { writeFileSync } from 'node:fs';
export const sign = (value: number) => (value > 0 ? 1 : -1);
export function fixed(value: number, digits: number) {
  if (Math.abs(value) >= 1e21) {
    return (value < 0 ? '-' : '') + BigInt(Math.abs(value)).toString() + '.' + '0'.repeat(digits);
  }
  const text = value.toFixed(digits);
  return Number(text) === 0 && text.startsWith('-') ? text.slice(1) : text;
}
export const ratio = (a: number, b: number) => (b > 0 ? fixed(a / b, 4) : '-');
export function folds(count: number, k: number) {
  return Array.from({ length: k }, (_, fold) => {
    const train: number[] = [];
    const test: number[] = [];
    for (let i = 0; i < count; i++) (i % k === fold ? test : train).push(i);
    return { train, test };
  });
}
export function binary(labels: number[], values: number[]) {
  let tp = 0;
  let fp = 0;
  let tn = 0;
  let fn = 0;
  for (let i = 0; i < labels.length; i++) {
    if (sign(values[i]) === 1) {
      if (labels[i] === 1) tp++;
      else fp++;
    } else if (labels[i] === -1) tn++;
    else fn++;
  }
  return { tp, fp, tn, fn, correct: tp + tn };
}
export function auc(labels: number[], values: number[]) {
  let sum = 0;
  let positive = 0;
  let negative = 0;
  for (const label of labels) {
    if (label === 1) positive++;
    else negative++;
  }
  for (let i = 0; i < labels.length; i++) {
    if (labels[i] === 1) {
      for (let j = 0; j < labels.length; j++) {
        if (labels[j] === -1) {
          if (values[i] > values[j]) sum++;
          else if (values[i] === values[j]) sum += 0.5;
        }
      }
    }
  }
  return sum / (positive * negative);
}
export function confusion(classes: number[], predictions: number[]) {
  const counts = Array.from({ length: 3 }, () => [0, 0, 0]);
  for (let i = 0; i < classes.length; i++) counts[classes[i] - 1][predictions[i] - 1]++;
  return counts;
}
export function write(path: string, lines: string[]) {
  writeFileSync(path, lines.length ? lines.join('\n') + '\n' : '', 'ascii');
}

import type { Kernel, Point } from './dataset.ts';
import { fixed } from './evaluation.ts';
export function value(kernel: Kernel, a: Point, b: Point) {
  if (kernel.kind === 'linear') return a[0] * b[0] + a[1] * b[1];
  if (kernel.kind === 'poly') {
    const s = kernel.gamma * (a[0] * b[0] + a[1] * b[1]) + kernel.coef0;
    let result = 1;
    for (let i = 0; i < kernel.degree; i++) result *= s;
    return result;
  }
  const e1 = a[0] - b[0];
  const e2 = a[1] - b[1];
  return Math.exp(-kernel.gamma * (e1 * e1 + e2 * e2));
}
export const matrix = (kernel: Kernel, points: Point[]) =>
  points.map((a) => points.map((b) => value(kernel, a, b)));
export const subset = (matrix: number[][], indices: number[]) =>
  indices.map((i) => indices.map((j) => matrix[i][j]));
export function description(kernel: Kernel) {
  return kernel.kind === 'linear'
    ? 'linear'
    : kernel.kind === 'poly'
      ? `poly degree ${kernel.degree} gamma ${fixed(kernel.gamma, 4)} coef0 ${fixed(kernel.coef0, 4)}`
      : `rbf gamma ${fixed(kernel.gamma, 4)}`;
}

import { read } from './dataset.ts';
import type { Example, MultiExample, Point, Kernel, Parameters } from './dataset.ts';
import * as kernels from './kernels.ts';
import * as smo from './smo.ts';
import type { Trainer } from './smo.ts';
import * as multiclass from './multiclass.ts';
import type { Models } from './multiclass.ts';
import { sign, fixed, ratio, folds, binary, auc, confusion, write } from './evaluation.ts';

interface Support {
  total: number;
  bound: number;
  free: number;
}
interface FoldResult {
  train: number;
  test: number;
  correct: number;
  support: number;
  passes: number;
  steps: number;
  converged: boolean;
}
interface Candidate {
  kernel: Kernel;
  C: number;
  correct: number;
  support: number;
  passes: number;
  steps: number;
  values: number[];
  folds: FoldResult[];
}
interface CrossValidation {
  combinations: Candidate[];
  best: Candidate[];
  ranking: Candidate[];
  selected: Candidate;
}
function support(model: Trainer): Support {
  let total = 0;
  let bound = 0;
  let free = 0;
  for (const a of model.alpha) {
    if (a > 0) {
      total++;
      if (a === model.C) bound++;
      else free++;
    }
  }
  return { total, bound, free };
}
const supportText = (s: Support) => `support_vectors ${s.total} bound ${s.bound} free ${s.free}`;
const runInfo = (model: Trainer | FoldResult) =>
  `passes ${'passes' in model ? model.passes : model.full + model.nonbound} steps ${model.steps} converged ${model.converged ? 'yes' : 'no'}`;
function objective(model: Trainer, alpha = model.alpha) {
  const sums = smo.trainingSums(model, alpha);
  let q = 0;
  let total = 0;
  for (let i = 0; i < alpha.length; i++) {
    q += alpha[i] * model.labels[i] * sums[i];
    total += alpha[i];
  }
  return { sums, q, dual: total - q / 2 };
}
function measure(model: Trainer, test: Example[]) {
  const result = objective(model);
  const values = result.sums.map((s) => s - model.b);
  const testValues = test.map((row) => smo.decision(model, row.point));
  let w1 = 0;
  let w2 = 0;
  for (let i = 0; i < model.alpha.length; i++) {
    w1 += model.alpha[i] * model.labels[i] * model.points[i][0];
    w2 += model.alpha[i] * model.labels[i] * model.points[i][1];
  }
  return {
    model,
    ...result,
    values,
    testValues,
    weights: [w1, w2],
    sv: support(model),
    trainCorrect: binary(model.labels, values).correct,
    testStats: binary(
      test.map((row) => row.label),
      testValues,
    ),
  };
}
type Measured = ReturnType<typeof measure>;
function crossValidate(train: Example[], p: Parameters, matrices: number[][][]): CrossValidation {
  const partition = folds(train.length, p.folds);
  const combinations: Candidate[] = [];
  const best: Candidate[] = [];
  for (const kernel of p.kernels) {
    const candidates: Candidate[] = [];
    for (const C of p.cs) {
      const result: Candidate = {
        kernel,
        C,
        correct: 0,
        support: 0,
        passes: 0,
        steps: 0,
        values: Array(train.length).fill(0),
        folds: [],
      };
      for (const fold of partition) {
        const model = smo.train(
          fold.train.map((i) => train[i].point),
          fold.train.map((i) => train[i].label),
          kernels.subset(matrices[kernel.index], fold.train),
          C,
          kernel,
          p,
        );
        let correct = 0;
        for (const i of fold.test) {
          result.values[i] = smo.decision(model, train[i].point);
          if (sign(result.values[i]) === train[i].label) correct++;
        }
        const sv = support(model);
        const passes = model.full + model.nonbound;
        result.folds.push({
          train: fold.train.length,
          test: fold.test.length,
          correct,
          support: sv.total,
          passes,
          steps: model.steps,
          converged: model.converged,
        });
        result.correct += correct;
        result.support += sv.total;
        result.passes += passes;
        result.steps += model.steps;
      }
      candidates.push(result);
      combinations.push(result);
    }
    best.push(candidates.slice().sort((a, b) => b.correct - a.correct || a.C - b.C)[0]);
  }
  const ranking = combinations
    .slice()
    .sort((a, b) => b.correct - a.correct || a.C - b.C || a.kernel.index - b.kernel.index);
  return { combinations, best, ranking, selected: ranking[0] };
}
function crossValidationLines(cv: CrossValidation, n: number, p: Parameters) {
  const lines = [`cross_validation folds ${p.folds} examples ${n}`];
  for (const best of cv.best) {
    lines.push(
      `best ${best.kernel.name} C ${fixed(best.C, 4)} correct ${best.correct}/${n} accuracy ${ratio(best.correct, n)}`,
    );
  }
  lines.push(`selected ${cv.selected.kernel.name} C ${fixed(cv.selected.C, 4)}`, 'ranking');
  cv.ranking.forEach((e, i) =>
    lines.push(`${i + 1} ${e.kernel.name} C ${fixed(e.C, 4)} correct ${e.correct}/${n}`),
  );
  lines.push(`cv_detail ${cv.selected.kernel.name} C ${fixed(cv.selected.C, 4)}`);
  cv.selected.folds.forEach((f, i) =>
    lines.push(
      `fold ${i + 1} train ${f.train} test ${f.test} correct ${f.correct} support_vectors ${f.support} ${runInfo(f)}`,
    ),
  );
  return lines;
}
function finalModelLines(result: Measured, train: Example[], test: Example[], p: Parameters) {
  const { model, q, dual, values, testValues, sv, trainCorrect, testStats, weights } = result;
  const n = train.length;
  const m = test.length;
  let sy = 0;
  let sg = 0;
  let maximum = -Infinity;
  let minimum = Infinity;
  for (let i = 0; i < n; i++) {
    maximum = Math.max(maximum, model.Q[i][i]);
    for (let j = 0; j < n; j++) {
      sy += model.labels[i] * model.labels[j] * model.Q[i][j];
      sg += model.Q[i][j] * model.Q[i][j];
      minimum = Math.min(minimum, model.Q[i][j]);
    }
  }
  const radius = maximum - minimum;
  const norm = Math.sqrt(q);
  const byClass = { positive: { bound: 0, free: 0 }, negative: { bound: 0, free: 0 } };
  let equality = 0;
  let xi = 0;
  let violations = 0;
  let maxViolation = 0;
  let estimatedErrors = 0;
  for (let i = 0; i < n; i++) {
    const a = model.alpha[i];
    const y = model.labels[i];
    const hinge = Math.max(0, 1 - y * values[i]);
    const r = y * values[i] - 1;
    equality += a * y;
    xi += hinge;
    const violation = a === 0 ? Math.max(0, -r) : a === model.C ? Math.max(0, r) : Math.abs(r);
    if (violation > p.tau) violations++;
    maxViolation = Math.max(maxViolation, violation);
    if (2 * a * radius + hinge >= 1) estimatedErrors++;
    if (a > 0) byClass[y === 1 ? 'positive' : 'negative'][a === model.C ? 'bound' : 'free']++;
  }
  const primal = q / 2 + model.C * xi;
  let inside = 0;
  let positiveSum = 0;
  let negativeSum = 0;
  let positives = 0;
  let negatives = 0;
  for (let i = 0; i < m; i++) {
    if (Math.abs(testValues[i]) < 1) inside++;
    if (test[i].label === 1) {
      positiveSum += testValues[i];
      positives++;
    } else {
      negativeSum += testValues[i];
      negatives++;
    }
  }
  const lines = [
    `model ${model.kernel.name}`,
    `kernel ${kernels.description(model.kernel)}`,
    `C ${fixed(model.C, 4)}`,
    `alignment ${fixed(sy / (n * Math.sqrt(sg)), 6)}`,
    `passes ${model.full + model.nonbound} full ${model.full} nonbound ${model.nonbound} converged ${model.converged ? 'yes' : 'no'}`,
    `examined ${model.examined} steps ${model.steps}`,
    `choice heuristic ${model.choice.heuristic} nonbound_loop ${model.choice.nonbound_loop} full_loop ${model.choice.full_loop}`,
    `clipping none ${model.clipping.none} lower ${model.clipping.lower} upper ${model.clipping.upper}`,
    supportText(sv),
    `b ${fixed(model.b, 6)}`,
    `equality ${fixed(equality, 6)}`,
  ];
  if (model.kernel.kind === 'linear') {
    lines.push(`w ${fixed(weights[0], 6)} ${fixed(weights[1], 6)}`);
  }
  const { positive, negative } = byClass;
  const { tp, fp, tn, fn, correct } = testStats;
  lines.push(
    `sv_by_class positive bound ${positive.bound} free ${positive.free} negative bound ${negative.bound} free ${negative.free}`,
    `norm ${fixed(norm, 6)} margin ${fixed(2 / norm, 6)}`,
    `dual_objective ${fixed(dual, 6)}`,
    `primal_objective ${fixed(primal, 6)}`,
    `duality_gap ${fixed(primal - dual, 6)}`,
    `kkt_violations ${violations} max ${fixed(maxViolation, 6)}`,
    `xi_alpha radius ${fixed(radius, 6)} errors ${estimatedErrors}/${n} accuracy ${ratio(n - estimatedErrors, n)}`,
    `train correct ${trainCorrect}/${n} accuracy ${ratio(trainCorrect, n)}`,
    `test correct ${correct}/${m} accuracy ${ratio(correct, m)} tp ${tp} fp ${fp} tn ${tn} fn ${fn}`,
    `test precision ${ratio(tp, tp + fp)} recall ${ratio(tp, tp + fn)} f1 ${ratio(2 * tp, 2 * tp + fp + fn)} auc ${fixed(
      auc(
        test.map((row) => row.label),
        testValues,
      ),
      4,
    )}`,
    `test inside_margin ${inside}`,
    `test mean_decision positive ${fixed(positiveSum / positives, 4)} negative ${fixed(negativeSum / negatives, 4)}`,
  );
  for (let i = 0; i < n; i++) {
    if (model.alpha[i] > 0) {
      lines.push(
        `sv ${train[i].id} y ${model.labels[i]} alpha ${fixed(model.alpha[i], 6)} f ${fixed(values[i], 4)} ${model.alpha[i] === model.C ? 'bound' : 'free'}`,
      );
    }
  }
  return lines;
}
function trainingLog(model: Trainer) {
  const lines = [`training_log ${model.kernel.name}`];
  for (let i = 0; i < model.records.length;) {
    const first = model.records[i];
    if (first.kind === 'full') {
      lines.push(
        `pass ${first.number} full examined ${first.examined} changed ${first.changed} dual_objective ${fixed(objective(model, first.alpha).dual, 6)}`,
      );
      i++;
    } else {
      let examined = 0;
      let changed = 0;
      let last = first.number;
      while (i < model.records.length && model.records[i].kind === 'nonbound') {
        const record = model.records[i++];
        examined += record.examined;
        changed += record.changed;
        last = record.number;
      }
      lines.push(`passes ${first.number}-${last} nonbound examined ${examined} changed ${changed}`);
    }
  }
  return lines;
}
function selectedAnalyses(selected: Measured, train: Example[], test: Example[], p: Parameters) {
  const { model } = selected;
  const n = train.length;
  const m = test.length;
  const path = [`c_path ${model.kernel.name}`];
  for (const C of p.cs) {
    const fitted =
      C === model.C ? model : smo.train(model.points, model.labels, model.Q, C, model.kernel, p);
    const result = measure(fitted, test);
    path.push(
      `C ${fixed(C, 4)} ${supportText(result.sv)} dual_objective ${fixed(result.dual, 6)} train ${result.trainCorrect}/${n} test ${result.testStats.correct}/${m} ${runInfo(fitted)}`,
    );
  }
  const learning = [`learning_curve ${model.kernel.name} C ${fixed(model.C, 4)}`];
  for (const fraction of p.learningCurve) {
    const size = Math.floor((n * fraction) / 100);
    const indices = Array.from({ length: size }, (_, i) => i);
    const fitted =
      size === n
        ? model
        : smo.train(
            model.points.slice(0, size),
            model.labels.slice(0, size),
            kernels.subset(model.Q, indices),
            model.C,
            model.kernel,
            p,
          );
    const result = measure(fitted, test);
    learning.push(
      `size ${size} support_vectors ${result.sv.total} train ${result.trainCorrect}/${size} test ${result.testStats.correct}/${m} ${runInfo(fitted)}`,
    );
  }
  return [trainingLog(model), path, learning];
}
const probability = (value: number, A: number, B: number) => 1 / (1 + Math.exp(A * value + B));
function calibrate(
  cv: Candidate,
  selected: Measured,
  train: Example[],
  test: Example[],
  p: Parameters,
) {
  const values = cv.values;
  const n = train.length;
  const m = test.length;
  const positives = train.filter((row) => row.label === 1).length;
  const negatives = n - positives;
  const targets = train.map((row) =>
    row.label === 1 ? (positives + 1) / (positives + 2) : 1 / (negatives + 2),
  );
  let A = 0;
  let B = Math.log((negatives + 1) / (positives + 1));
  const nll = () => {
    let sum = 0;
    for (let i = 0; i < n; i++) {
      const pr = probability(values[i], A, B);
      const target = targets[i];
      sum += target * Math.log(pr) + (1 - target) * Math.log(1 - pr);
    }
    return -sum;
  };
  const lines = [
    `calibration ${selected.model.kernel.name} C ${fixed(selected.model.C, 4)} positives ${positives} negatives ${negatives}`,
    `start A ${fixed(A, 6)} B ${fixed(B, 6)} nll ${fixed(nll(), 6)}`,
  ];
  for (let iteration = 1; iteration <= p.newtonIterations; iteration++) {
    let g1 = 0;
    let g2 = 0;
    let h11 = 0;
    let h21 = 0;
    let h22 = 0;
    for (let i = 0; i < n; i++) {
      const v = values[i];
      const pr = probability(v, A, B);
      const target = targets[i];
      g1 += v * (target - pr);
      g2 += target - pr;
      h11 += v * v * pr * (1 - pr);
      h21 += v * pr * (1 - pr);
      h22 += pr * (1 - pr);
    }
    const det = h11 * h22 - h21 * h21;
    const nextA = A - (h22 * g1 - h21 * g2) / det;
    const nextB = B - (h11 * g2 - h21 * g1) / det;
    A = nextA;
    B = nextB;
    lines.push(`iteration ${iteration} A ${fixed(A, 6)} B ${fixed(B, 6)} nll ${fixed(nll(), 6)}`);
  }
  const probabilities = selected.testValues.map((value) => probability(value, A, B));
  const bins = Array.from({ length: 5 }, () => ({ count: 0, sum: 0, positive: 0 }));
  let logSum = 0;
  let brierSum = 0;
  for (let i = 0; i < m; i++) {
    const pr = probabilities[i];
    const positive = test[i].label === 1;
    logSum += Math.log(positive ? pr : 1 - pr);
    const error = pr - (positive ? 1 : 0);
    brierSum += error * error;
    const bin = bins[Math.min(4, Math.floor(pr * 5))];
    bin.count++;
    bin.sum += pr;
    if (positive) bin.positive++;
  }
  lines.push(`test log_loss ${fixed(-logSum / m, 6)} brier ${fixed(brierSum / m, 6)}`);
  const ranges = ['0.0-0.2', '0.2-0.4', '0.4-0.6', '0.6-0.8', '0.8-1.0'];
  bins.forEach((bin, i) =>
    lines.push(
      `bin ${ranges[i]} count ${bin.count} mean_probability ${bin.count ? fixed(bin.sum / bin.count, 4) : '-'} positive_rate ${ratio(bin.positive, bin.count)}`,
    ),
  );
  const closest = Array.from({ length: m }, (_, i) => i)
    .sort((a, b) => Math.abs(selected.testValues[a]) - Math.abs(selected.testValues[b]) || a - b)
    .slice(0, 5);
  for (const i of closest) {
    lines.push(
      `closest ${test[i].id} label ${test[i].label} decision ${fixed(selected.testValues[i], 4)} probability ${fixed(probabilities[i], 4)}`,
    );
  }
  return { A, B, probabilities, lines };
}
type Calibration = ReturnType<typeof calibrate>;
type Weights = [number, number, number];
const linearValue = (weights: Weights, point: Point) =>
  weights[0] * point[0] + weights[1] * point[1] + weights[2];
function pegasos(train: Example[], test: Example[], comparison: Measured, p: Parameters) {
  const { lambda, iterations, seed } = p.pegasos;
  const n = train.length;
  const m = test.length;
  let state = seed;
  let w1 = 0;
  let w2 = 0;
  let w0 = 0;
  let s1 = 0;
  let s2 = 0;
  let s0 = 0;
  let updates = 0;
  const lines = [`pegasos lambda ${fixed(lambda, 4)} iterations ${iterations} seed ${seed}`];
  for (let t = 1; t <= iterations; t++) {
    state = (48271 * state) % 2147483647;
    const row = train[state % n];
    const eta = 1 / (lambda * t);
    const sigma = 1 - eta * lambda;
    const value = w1 * row.point[0] + w2 * row.point[1] + w0;
