      const point: Point = [p.xMin + (c + 0.5) * dx, p.yMax - (r + 0.5) * dy];
      const values = finals.map((result) => smo.decision(result.model, point));
      const v = values[selected.model.kernel.index];
      binaryGrid[r].push(v >= 1 ? '+' : v > 0 ? '.' : v > -1 ? '-' : ' ');
      const digit = Math.min(9, Math.floor(probability(v, calibration.A, calibration.B) * 10));
      probabilityGrid[r].push(String(digit));
      levels[digit]++;
