    let outside = 0;
    let points = 0;
    for (let i = 0; i < rows.length; i++) {
      const c = Math.floor((rows[i].point[0] - p.xMin) / dx);
      const r = Math.floor((p.yMax - rows[i].point[1]) / dy);
      if (c < 0 || c >= W || r < 0 || r >= H) {
        outside++;
        continue;
      }
      const cell = r * W + c;
      if (owners[cell] < 0) {
        owners[cell] = i;
        points++;
      } else if (prefer(i, owners[cell])) owners[cell] = i;
    }
    for (let r = 0; r < H; r++) {
      for (let c = 0; c < W; c++) {
        if (owners[r * W + c] >= 0) grid[r][c] = character(owners[r * W + c]);
      }
    }
    return { outside, points };
  }
  const binaryOverlay = overlay(
    binaryGrid,
    train,
    (i, old) => selected.model.alpha[i] > 0 && !(selected.model.alpha[old] > 0),
    (i) =>
      train[i].label === 1
        ? selected.model.alpha[i] > 0
          ? 'X'
          : 'x'
        : selected.model.alpha[i] > 0
          ? 'O'
          : 'o',
  );
  const multiOverlay = overlay(
    multiGrid,
    multiTrain,
    () => false,
    (i) => String(multiTrain[i].class),
  );
  const count = (grid: string[][], char: string) =>
    grid.reduce((total, row) => total + row.filter((c) => c === char).length, 0);
  const frame = (grid: string[][]) => {
    const border = '+' + '-'.repeat(W) + '+';
    return [border, ...grid.map((row) => '|' + row.join('') + '|'), border];
  };
  const lines = [
    `binary ${selected.model.kernel.name} C ${fixed(selected.model.C, 4)}`,
    `x ${fixed(p.xMin, 4)} ${fixed(p.xMax, 4)} y ${fixed(p.yMin, 4)} ${fixed(p.yMax, 4)} grid ${W}x${H}`,
    ...frame(binaryGrid),
    `cells outer_positive ${count(binaryGrid, '+')} inner_positive ${count(binaryGrid, '.')} inner_negative ${count(binaryGrid, '-')} outer_negative ${count(binaryGrid, ' ')} points ${binaryOverlay.points} outside ${binaryOverlay.outside}`,
    '',
    `probability ${selected.model.kernel.name} A ${fixed(calibration.A, 6)} B ${fixed(calibration.B, 6)}`,
    ...frame(probabilityGrid),
    `levels ${levels.join(' ')}`,
    '',
    'grid_agreement',
  ];
  for (let a = 0; a < finals.length; a++) {
    for (let b = a + 1; b < finals.length; b++) {
      let agreement = 0;
      let positiveA = 0;
      let positiveB = 0;
      for (let cell = 0; cell < W * H; cell++) {
        if (signs[a][cell] === signs[b][cell]) agreement++;
        if (signs[a][cell] === 1) positiveA++;
        if (signs[b][cell] === 1) positiveB++;
      }
      lines.push(
        `${finals[a].model.kernel.name} ${finals[b].model.kernel.name} ${agreement}/${W * H} positive ${positiveA} ${positiveB}`,
      );
    }
  }
  lines.push(
    '',
    `multiclass ${multiKernel.name} C ${fixed(p.multiC, 4)}`,
    ...frame(multiGrid),
    `cells class1 ${count(multiGrid, ' ')} class2 ${count(multiGrid, '.')} class3 ${count(multiGrid, ':')} disagree ${count(multiGrid, '?')} points ${multiOverlay.points} outside ${multiOverlay.outside}`,
  );
  return lines;
}
