import type { Point, MultiExample, Kernel, Parameters } from './dataset.ts';
import { matrix, subset } from './kernels.ts';
import { train as fit, decision } from './smo.ts';
import type { Trainer } from './smo.ts';
export const pairs = [
  [1, 2],
  [1, 3],
  [2, 3],
];
export interface Models {
  ovr: Trainer[];
  ovo: Trainer[];
}
export function train(rows: MultiExample[], kernel: Kernel, C: number, params: Parameters): Models {
  const points = rows.map((row) => row.point);
  const Q = matrix(kernel, points);
  const ovr = [1, 2, 3].map((k) =>
    fit(
      points,
      rows.map((row) => (row.class === k ? 1 : -1)),
      Q,
      C,
      kernel,
      params,
    ),
  );
  const ovo = pairs.map(([a, b]) => {
    const indices: number[] = [];
    for (let i = 0; i < rows.length; i++) {
      if (rows[i].class === a || rows[i].class === b) indices.push(i);
    }
    return fit(
      indices.map((i) => points[i]),
      indices.map((i) => (rows[i].class === a ? 1 : -1)),
      subset(Q, indices),
      C,
      kernel,
      params,
    );
  });
  return { ovr, ovo };
}
export function classify(models: Models, point: Point) {
  const g = models.ovr.map((model) => decision(model, point));
  const h = models.ovo.map((model) => decision(model, point));
  const votes = [0, 0, 0];
  const scores = [0, 0, 0];
  let ovr = 0;
  for (let k = 1; k < 3; k++) if (g[k] > g[ovr]) ovr = k;
  for (let i = 0; i < pairs.length; i++) {
    const [a, b] = pairs[i];
    votes[(h[i] > 0 ? a : b) - 1]++;
    scores[a - 1] += h[i];
    scores[b - 1] -= h[i];
  }
  const max = Math.max(...votes);
  let ovo = -1;
  let tied = 0;
  for (let k = 0; k < 3; k++) {
    if (votes[k] === max) {
      tied++;
      if (ovo < 0 || scores[k] > scores[ovo]) ovo = k;
    }
  }
  return { g, h, votes, scores, ovr: ovr + 1, ovo: ovo + 1, voteTie: tied > 1 };
}

import type { Point, Kernel, Parameters } from './dataset.ts';
import { value } from './kernels.ts';
interface Pass {
  number: number;
  examined: number;
  changed: number;
}
export type PassRecord = Pass & ({ kind: 'full'; alpha: number[] } | { kind: 'nonbound' });
export class Trainer {
  alpha: number[];
  errors: number[];
  b = 0;
  full = 0;
  nonbound = 0;
  examined = 0;
  steps = 0;
  converged = false;
  choice = { heuristic: 0, nonbound_loop: 0, full_loop: 0 };
  clipping = { none: 0, lower: 0, upper: 0 };
  records: PassRecord[] = [];
  constructor(
    public points: Point[],
    public labels: number[],
    public Q: number[][],
    public C: number,
    public kernel: Kernel,
    private params: Parameters,
  ) {
    this.alpha = points.map(() => 0);
    this.errors = labels.map((y) => -y);
  }
  nonBound(a: number) {
    return a > 0 && a < this.C;
  }
  snap(a: number) {
    return a < 1e-8 ? 0 : a > this.C - 1e-8 ? this.C : a;
  }
  take(i1: number, i2: number) {
    if (i1 === i2) return false;
    const old1 = this.alpha[i1];
    const old2 = this.alpha[i2];
    const y1 = this.labels[i1];
    const y2 = this.labels[i2];
    const e1 = this.errors[i1];
    const e2 = this.errors[i2];
    const C = this.C;
    const lo = y1 !== y2 ? Math.max(0, old2 - old1) : Math.max(0, old2 + old1 - C);
    const hi = y1 !== y2 ? Math.min(C, C + old2 - old1) : Math.min(C, old2 + old1);
    if (lo === hi) return false;
    const k11 = this.Q[i1][i1];
    const k12 = this.Q[i1][i2];
    const k22 = this.Q[i2][i2];
    const eta = k11 + k22 - 2 * k12;
    if (eta <= 0) return false;
    let a2 = old2 + (y2 * (e1 - e2)) / eta;
    let clipping: keyof Trainer['clipping'] = 'none';
    if (a2 < lo) {
      a2 = lo;
      clipping = 'lower';
    } else if (a2 > hi) {
      a2 = hi;
      clipping = 'upper';
    }
    a2 = this.snap(a2);
    if (Math.abs(a2 - old2) < this.params.eps * (a2 + old2 + this.params.eps)) return false;
    const a1 = this.snap(old1 + y1 * y2 * (old2 - a2));
    const t1 = y1 * (a1 - old1);
    const t2 = y2 * (a2 - old2);
    const b1 = e1 + t1 * k11 + t2 * k12 + this.b;
    const b2 = e2 + t1 * k12 + t2 * k22 + this.b;
