    const delta = nextB - this.b;
    for (let i = 0; i < this.points.length; i++) {
      this.errors[i] = this.errors[i] + (t1 * this.Q[i1][i] + t2 * this.Q[i2][i] - delta);
    }
    if (this.nonBound(a1)) this.errors[i1] = 0;
    if (this.nonBound(a2)) this.errors[i2] = 0;
    this.alpha[i1] = a1;
    this.alpha[i2] = a2;
