    let largest = -1;
    for (let i = 0; i < this.points.length; i++) {
      if (i !== i2 && this.nonBound(this.alpha[i])) {
        const d = Math.abs(this.errors[i] - this.errors[i2]);
        if (d > largest) {
          partner = i;
          largest = d;
        }
      }
    }
    if (partner >= 0 && this.take(partner, i2)) {
      this.choice.heuristic++;
      return 1;
    }
    for (let i = 0; i < this.points.length; i++) {
      if (this.nonBound(this.alpha[i]) && this.take(i, i2)) {
        this.choice.nonbound_loop++;
        return 1;
      }
    }
    for (let i = 0; i < this.points.length; i++) {
      if (this.take(i, i2)) {
        this.choice.full_loop++;
        return 1;
      }
    }
    return 0;
  }
  run() {
    let all = true;
