      const before = this.examined;
      let changed = 0;
      for (let i = 0; i < this.points.length; i++) {
        if (all || this.nonBound(this.alpha[i])) changed += this.examine(i);
      }
      if (all) this.full++;
      else this.nonbound++;
      const record = {
        number: this.full + this.nonbound,
        examined: this.examined - before,
        changed,
      };
      this.records.push(
        all
          ? { ...record, kind: 'full', alpha: this.alpha.slice() }
          : { ...record, kind: 'nonbound' },
      );
      if (all && changed === 0) {
        this.converged = true;
        break;
      }
      if (this.full + this.nonbound === this.params.maxPasses) break;
      if (all) all = false;
      else if (changed === 0) all = true;
    }
