export const train = (
  points: Point[],
  labels: number[],
  Q: number[][],
  C: number,
  kernel: Kernel,
  params: Parameters,
) => new Trainer(points, labels, Q, C, kernel, params).run();
export function decision(model: Trainer, point: Point) {
  let sum = 0;
  for (let j = 0; j < model.alpha.length; j++) {
    if (model.alpha[j] > 0) {
      sum += model.alpha[j] * model.labels[j] * value(model.kernel, model.points[j], point);
    }
  }
  return sum - model.b;
}
export function trainingSums(model: Trainer, alpha = model.alpha) {
  return model.points.map((_, i) => {
    let sum = 0;
    for (let j = 0; j < alpha.length; j++) {
      if (alpha[j] > 0) sum += alpha[j] * model.labels[j] * model.Q[i][j];
    }
    return sum;
  });
}
